mapper.select:
SELECT u.id, u.name, u.province, u.address, u.admin_department, u.website, u.admission_website, u.contact_number, u.type, u.level, u.student_count, u.teacher_count, u.library_count, u.campus_area, u.introduction, u.departments, u.majors, u.admission_rules, u.scholarships, u.accommodation, u.contact_info, u.logo, GROUP_CONCAT(DISTINCT f.feature_name) as features FROM university u LEFT JOIN university_feature f ON u.id = f.university_id
AND u.name LIKE CONCAT('%', #{params.name}, '%')
AND u.province = #{params.province}
AND u.type = #{params.type}
AND u.level = #{params.level}
AND u.admin_department = #{params.adminDepartment}
GROUP BY u.id, u.name, u.province, u.address, u.admin_department, u.website, u.admission_website, u.contact_number, u.type, u.level, u.student_count, u.teacher_count, u.library_count, u.campus_area, u.introduction, u.departments, u.majors, u.admission_rules, u.scholarships, u.accommodation, u.contact_info, u.logo ORDER BY u.id DESC

SELECT u.name as universityName, a.year, SUM(a.plan_count) as totalPlanCount, SUM(a.actual_count) as totalActualCount, AVG(a.score_required) as averageScore, MIN(a.lowest_rank) as bestRank FROM university u LEFT JOIN admission a ON u.id = a.university_id WHERE u.id = #{universityId}
AND a.year = #{year}
GROUP BY u.name, a.year ORDER BY a.year DESC
